import { processPresetsPolyfill, type PresetsPolyfillData } from '@wix/builder-presets-polyfill'
import { WIX_WARMUP_DATA_ELEMENT_ID, INIT_PRESETS_POLYFILL_SSR_MARK } from './constants'

/**
 * Initialize presets polyfill - applies CSS-defined preset values as DOM attributes
 * This runs before hydration to ensure preset attributes are available on SSR
 */
export const initPresetsPolyfillSsr = () => {
	try {
		const startMarkName = `${INIT_PRESETS_POLYFILL_SSR_MARK}_start`
		const endMarkName = `${INIT_PRESETS_POLYFILL_SSR_MARK}_end`
		performance.mark(startMarkName)

		// Parse polyfill configuration from warmup data embedded in the page
		const warmupData = JSON.parse(document.getElementById(WIX_WARMUP_DATA_ELEMENT_ID)?.textContent || '{}')
		const builderComponent = (warmupData.builderComponent || {}) as { presetsPolyfill: PresetsPolyfillData }
		const presetsPolyfill = builderComponent?.presetsPolyfill

		// Early return if no polyfill data - no need to measure anything
		if (!presetsPolyfill) {
			return
		}

		const componentsCount = Object.keys(presetsPolyfill).length

		try {
			processPresetsPolyfill(presetsPolyfill)
		} finally {
			performance.mark(endMarkName)
			// Store componentsCount in the measure's detail for later retrieval
			performance.measure(INIT_PRESETS_POLYFILL_SSR_MARK, {
				start: startMarkName,
				end: endMarkName,
				detail: { componentsCount },
			})
		}
	} catch (error) {
		console.error('Error initializing presets polyfill', error)
	}
}

// Auto-initialize polyfill when module loads in browser environment
if (typeof window !== 'undefined') {
	initPresetsPolyfillSsr()
}
